create extension if not exists pgcrypto; create table courses (id text primary key,title text not null,published boolean not null default false); create table units (id text primary key,course_id text not null references courses(id),title text not null); create table topics (id text primary key,unit_id text not null references units(id),title text not null); create table objectives (id text primary key,topic_id text not null references topics(id),title text not null,m4_eligible boolean not null default true); create table resources (id text primary key,objective_id text not null references objectives(id),source text not null check(source in ('teacher','external')),published boolean not null default false); create table exercise_versions (id text primary key,objective_id text not null references objectives(id),version integer not null,unique(objective_id,version)); create table attempts (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),objective_id text not null references objectives(id),exercise_version_id text not null references exercise_versions(id),idempotency_key text not null,correct boolean not null,help_level text not null check(help_level in ('none','diagnosis','hint','solution')),created_at timestamptz not null default now(),unique(user_id,idempotency_key)); create table evidence_slots (user_id uuid not null references auth.users(id),objective_id text not null references objectives(id),exercise_version_id text not null references exercise_versions(id),attempt_id uuid not null references attempts(id),primary key(user_id,objective_id,exercise_version_id)); create table context_snapshots (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),objective_id text not null references objectives(id),snapshot jsonb not null,created_at timestamptz not null default now()); create table mastery (user_id uuid not null references auth.users(id),objective_id text not null references objectives(id),level int not null check(level between 0 and 4),review_due_at timestamptz not null,primary key(user_id,objective_id)); alter table attempts enable row level security; alter table evidence_slots enable row level security; alter table context_snapshots enable row level security; alter table mastery enable row level security; create policy "own attempts" on attempts for all using (user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own evidence slots" on evidence_slots for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own snapshots" on context_snapshots for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own mastery" on mastery for all using(user_id=auth.uid()) with check(user_id=auth.uid()); alter table courses enable row level security; alter table units enable row level security; alter table topics enable row level security; alter table objectives enable row level security; alter table resources enable row level security; alter table exercise_versions enable row level security; create policy "published courses read" on courses for select using(published); create policy "hierarchy read" on units for select using(exists(select 1 from courses where courses.id=units.course_id and courses.published)); create policy "topics read" on topics for select using(exists(select 1 from units join courses on courses.id=units.course_id where units.id=topics.unit_id and courses.published)); create policy "objectives read" on objectives for select using(exists(select 1 from topics join units on units.id=topics.unit_id join courses on courses.id=units.course_id where topics.id=objectives.topic_id and courses.published)); create policy "published resources read" on resources for select using(published); create policy "exercise read" on exercise_versions for select using(exists(select 1 from objectives join topics on topics.id=objectives.topic_id join units on units.id=topics.unit_id join courses on courses.id=units.course_id where objectives.id=exercise_versions.objective_id and courses.published)); insert into storage.buckets(id,name,public)values('attempt-work','attempt-work',false)on conflict do nothing; create policy "own attempt-work objects" on storage.objects for all using(bucket_id='attempt-work' and (storage.foldername(name))[1]=auth.uid()::text)with check(bucket_id='attempt-work' and (storage.foldername(name))[1]=auth.uid()::text);;
